import type { CurriculumEntry } from "@/lib/curriculum";

export interface HocaefendiVocabularyItem {
  readonly word: string;
  readonly tr: string;
  readonly fr: string;
  readonly nl: string;
}

export interface HocaefendiCurriculumItem {
  readonly weekNumber: number;
  readonly grade: number;
  readonly title: string;
  readonly rawTitle: string;
  readonly summary: string;
  readonly vocab: readonly HocaefendiVocabularyItem[];
  readonly youtubeUrl: string;
  readonly videoId: string;
  readonly body: string;
}

const monthSlugs: Record<number, string> = {
  1: "ocak",
  2: "subat",
  3: "mart",
  4: "nisan",
  5: "mayis",
  6: "haziran",
  7: "temmuz",
  8: "agustos",
  9: "eylul",
  10: "ekim",
  11: "kasim",
  12: "aralik",
};

function makeHocaefendiEntryId(month: number, week: number, grade: number = 1): string {
  const prefix = grade === 1 ? "" : `g${grade}-`;
  const monthSlug = monthSlugs[month] ?? `m${month}`;
  return `${prefix}hocaefendi-dinleme-${monthSlug}-${week}`;
}

