    body: "Kalp ile Allah dönme ve tevbe etme. konulu bu sohbette; namazın müminin miracı olduğu, günde beş vakit Allah'ın huzurunda durmanın kalbe verdiği huzur ve namazı vaktinde huşuyla kılmanın önemi samimiyetle anlatılmaktadır.\n\n📚 **Kelimeler ve Anlamları**:\n• **Uhuvvet**: İman bağıyla birbirini öz kardeş bilmek, sevgi ve fedakarlıkla kenetlenmek. (NL: Echte spirituele broederschap en verbondenheid / FR: Fraternité spirituelle profonde et solidarité d'âme)\n• **Kardeşlik Hukuku**: Müminlerin birbirine karşı taşımak zorunda olduğu saygı, sevgi, yardım ve hürmet hakları. (NL: De heilige rechten en plichten van oprechte broederschap / FR: Les devoirs sacrés et exigences morales de la fraternité)\n• **Sadakat**: Verilen söze, dostluğa ve davaya zor zamanlarda dahi sımsıkı bağlı kalmak. (NL: Trouw, betrouwbaarheid en loyaliteit in alle omstandigheden / FR: Fidélité inébranlable et loyauté absolue)\n• **Sebat**: Başlanan hayırlı bir işte kararlılıkla devam etmek, yılmamak ve sebat göstermek. (NL: Volharding en standvastigheid in het goede / FR: Persévérance inébranlable et ténacité vertueuse)\n• **Müsamaha**: İnsanların kusurlarını hoş görüp anlayışla karşılamak, bağışlayıcı olmak. (NL: Verdraagzaamheid, vergevensgezindheid en clementie / FR: Tolérance bienveillante et indulgence fraternelle)",
