    body: "Güzellikler sana uğrayıp geçiyor muhakkak sahip değilsin iddia edemezsin. Hocaefendi, Üstadı anlatıyor başlıklı bu derste imanın, güzel ahlakın ve samimi kulluğun hayatımızdaki önemi vurgulanmaktadır.\n\n📚 **Kelimeler ve Anlamları**:\n• **İnayet**: Zor ve sıkıntılı zamanlarda Allah'ın kulunu özel koruması ve yardımıyla kuşatması. (NL: Bijzondere goddelijke bescherming en bijstand in nood / FR: Providence protectrice et assistance divine particulière)\n• **Tahkîkî İman**: Taklitten ve körü körüne inanmaktan uzak, delil ve tefekkürle kalbe nakşolmuş sarsılmaz iman. (NL: Diep gefundeerd en onderzocht geloof dat onwankelbaar is / FR: Foi vérifiée, raisonnée et solidement ancrée dans le cœur)\n• **Tefekkür**: Kainattaki intizamı ve ilahi sanatları derin düşünceyle inceleyip ibret alma. (NL: Diepzinnige meditatie over de schepping en wijsheid / FR: Méditation contemplative sur l'ordre et la beauté de la création)\n• **Sabr-ı Cemîl**: Şikayet etmeden, vakar ve asaletle gösterilen güzel ve rızalı sabır. (NL: Schone en waardige geduld zonder klagen / FR: Patience noble et belle sans plainte ni amertume)\n• **Metanet**: Büyük acılar ve imtihanlar karşısında sarsılmadan ayakta durma cesareti ve sabrı. (NL: Geestelijke standvastigheid en kalme moed bij rampspoed / FR: Fermeté stoïque et sérénité courageuse dans l'épreuve)",
