    body: "Ağaçtan suya düşenler, kamp hatıraları konulu bu sohbette; namazın müminin miracı olduğu, günde beş vakit Allah'ın huzurunda durmanın kalbe verdiği huzur ve namazı vaktinde huşuyla kılmanın önemi samimiyetle anlatılmaktadır.\n\n📚 **Kelimeler ve Anlamları**:\n• **Kin ve Garaz**: İnsanlara karşı kalpte düşmanlık ve intikam duygusu besleme çirkinliği. (NL: Wrok en haatdragendheid die de ziel vergiftigen / FR: Rancune tenace et animosité corrosive pour le cœur)\n• **İ'lâ-yı Kelimetullah**: Allah'ın adını, sevgisini, merhametini ve adaletini yeryüzünün her köşesine ulaştırma ideali. (NL: Het verheffen van Gods naam en vrede over de hele wereld / FR: Le noble idéal de faire rayonner le nom et l'amour de Dieu)\n• **İhsan Şuuru**: Her nefeste ve her işte Allah'ın huzurunda olduğunun uyanık bilinciyle yaşamak. (NL: De levendige gewaarwording van Gods constante aanwezigheid / FR: La conscience perpétuelle et vivante de la présence divine)\n• **Üsve-i Hasene**: Her yönüyle taklit edilecek en mükemmel ahlak timsali olan Efendimiz (sav). (NL: Het mooiste rolmodel van volmaakte zedelijkheid / FR: L'archétype exemplaire de la perfection morale)\n• **Sünnet-i Seniyye**: Peygamber Efendimiz'in (sav) nurlu hayatı, sözleri ve bize miras bıraktığı örnek ahlakı. (NL: Het verheven voorbeeld en de leefwijze van de Profeet (vzmh) / FR: La noble tradition et voie exemplaire du Prophète (pssl))",
