/**
 * Belirtilen sınıf (1-6) için 48 haftalık Hocaefendi müfredat kayıtlarını CurriculumEntry formatında döner.
 */
export function getHocaefendiEntriesForGrade(grade: number): CurriculumEntry[] {
  const gradeLists: Record<number, readonly HocaefendiCurriculumItem[]> = {
    1: hocaefendiGrade1Curriculum,
    2: hocaefendiGrade2Curriculum,
    3: hocaefendiGrade3Curriculum,
    4: hocaefendiGrade4Curriculum,
    5: hocaefendiGrade5Curriculum,
    6: hocaefendiGrade6Curriculum,
  };

  const list = gradeLists[grade] ?? hocaefendiGrade1Curriculum;

  return list.map((item, index) => {
    const monthIndex = Math.floor(index / 4);
    const weekInMonth = (index % 4) + 1;
    const monthNumber = ((monthIndex + 8) % 12) + 1;
    const year = monthIndex < 4 ? 2026 : 2027;

    const id = makeHocaefendiEntryId(monthNumber, weekInMonth, grade);

    return {
      id,
      title: item.title,
      month: monthNumber,
      week: weekInMonth,
      year,
      categoryId: "hocaefendi-dinleme",
      body: item.body,
      pdfUrl: undefined,
      resourceUrl: item.youtubeUrl,
      isExtra: false,
    };
  });
}

/**
 * 6 sınıfın tamamı için toplam 288 kaydı birleştirilmiş tek bir dizi olarak döner.
 */
export function getAllHocaefendiEntries(): CurriculumEntry[] {
  const all: CurriculumEntry[] = [];
  for (let g = 1; g <= 6; g++) {
    all.push(...getHocaefendiEntriesForGrade(g));
  }
  return all;
}
